insert into public.profile (id, data) values (1, '{"name":"Irsyad Ghibran, S.T.","first":"Irsyad","last":"Ghibran, S.T.","title":"Metallurgical Engineer","roles":["Process Engineering","Extractive Metallurgy","Process Analysis","Laboratory Analysis"],"headline":"Process Engineer | Extractive Metallurgist | Laboratory Analyst","openToWork":true,"status":"Open to opportunities","location":"Surabaya, Indonesia","highlight":"","photo":"","logo":"","email":"","linkedin":"","github":"","cv":{"src":"","name":""},"lead":"Metallurgical Engineering graduate of UPN \"Veteran\" Yogyakarta with research and internship experience in extractive metallurgy.","about":"I bring strong analytical skills, precision, and a willingness to keep learning and adapting, so I can contribute to the metallurgical industry.","education":{"school":"UPN \"Veteran\" Yogyakarta","faculty":"Faculty of Mineral Technology","degree":"Bachelor of Metallurgical Engineering","years":"","gpa":"3.xx / 4.00","focus":"Extractive Metallurgy","courses":"Extractive Metallurgy, Hydrometallurgy, Pyrometallurgy, Mineral Processing, Physical Metallurgy, Thermodynamics of Materials, Corrosion Engineering","thesis":"Effect of Sulfuric Acid Concentration and Temperature on Nickel Recovery from Laterite Ore by Atmospheric Leaching","logo":""},"tr":{"title":"Sarjana Teknik Metalurgi","status":"Terbuka untuk peluang kerja","lead":"Lulusan Teknik Metalurgi UPN \"Veteran\" Yogyakarta dengan pengalaman penelitian dan magang di bidang extractive metallurgy.","about":"Saya memiliki kemampuan analitis, ketelitian, serta kemauan untuk terus belajar dan beradaptasi guna berkontribusi dalam industri metalurgi.","focus":"Metalurgi Ekstraksi","courses":"Metalurgi Ekstraksi, Hidrometalurgi, Pirometalurgi, Pengolahan Mineral, Metalurgi Fisik, Termodinamika Material, Teknik Korosi","thesis":"Pengaruh Konsentrasi Asam Sulfat dan Temperatur terhadap Perolehan Nikel dari Bijih Laterit dengan Pelindian Atmosferik"}}'::jsonb) on conflict (id) do update set data = excluded.data, updated_at = now();
