insert into public.projects (id, title, subtitle, category, year, icon, published, tags, description, demo_url, repo_url, photos, tr, sort) values ('p1', 'Atmospheric Leaching of Nickel Laterite', 'Hydrometallurgy · Final research', 'Research', 2025, 'flask', true, array['Leaching','Nickel','AAS']::text[], 'Studied the effect of acid concentration, temperature, and time on nickel recovery from laterite ore, with metal content measured by AAS.', '', '', '[]'::jsonb, '{"s":"Hidrometalurgi · Penelitian akhir","d":"Meneliti pengaruh konsentrasi asam, temperatur, dan waktu terhadap perolehan nikel dari bijih laterit, dengan kadar logam diukur menggunakan AAS."}'::jsonb, 0);
insert into public.projects (id, title, subtitle, category, year, icon, published, tags, description, demo_url, repo_url, photos, tr, sort) values ('p2', 'Ore Characterization with XRD & XRF', 'Mineralogy · Laboratory analysis', 'Research', 2024, 'microscope', true, array['XRD','XRF','Mineralogy']::text[], 'Identified the mineral phases and elemental composition of ore samples to recommend a suitable extraction route.', '', '', '[]'::jsonb, '{"s":"Mineralogi · Analisis laboratorium","d":"Mengidentifikasi fasa mineral dan komposisi unsur sampel bijih untuk merekomendasikan jalur ekstraksi yang sesuai."}'::jsonb, 1);
insert into public.projects (id, title, subtitle, category, year, icon, published, tags, description, demo_url, repo_url, photos, tr, sort) values ('p3', 'Smelter Process Efficiency Review', 'Internship project', 'Internship', 2025, 'factory', true, array['Pyrometallurgy','Process Data']::text[], 'Reviewed furnace operating data to find losses in energy use and metal recovery, and proposed practical improvements.', '', '', '[]'::jsonb, '{"s":"Proyek magang","d":"Meninjau data operasi tungku untuk menemukan kehilangan energi dan perolehan logam, lalu mengusulkan perbaikan praktis."}'::jsonb, 2);
insert into public.projects (id, title, subtitle, category, year, icon, published, tags, description, demo_url, repo_url, photos, tr, sort) values ('p4', 'Mass Balance of a Copper Concentrate Circuit', 'Process analysis', 'Case Study', 2024, 'gauge', true, array['Mass Balance','Copper','Spreadsheet']::text[], 'Built a mass balance model of a flotation circuit to trace copper losses between stages and test what-if scenarios.', '', '', '[]'::jsonb, '{"s":"Analisis proses","d":"Membangun model neraca massa sirkuit flotasi untuk menelusuri kehilangan tembaga antar tahap dan menguji skenario perubahan."}'::jsonb, 3);
insert into public.case_studies (id, title, context, year, icon, tags, problem, approach, result, photos, tr, sort) values ('cs1', 'Raising Nickel Recovery in Atmospheric Leaching', 'Final research · Hydrometallurgy lab', 2025, 'flask', array['Leaching','Design of Experiments','AAS']::text[], 'Nickel recovery from low-grade laterite stayed below 60% at standard leaching conditions, making the route uneconomical.', 'Ran a factorial experiment on acid concentration, temperature and time, measured dissolved Ni with AAS, and checked residues with XRD.', 'Identified the condition window that lifted recovery to about 85% (example figure) while limiting iron co-dissolution.', '[]'::jsonb, '{"t":"Meningkatkan Perolehan Nikel pada Pelindian Atmosferik","ctx":"Penelitian akhir · Lab hidrometalurgi","problem":"Perolehan nikel dari laterit kadar rendah tetap di bawah 60% pada kondisi pelindian standar sehingga jalurnya tidak ekonomis.","approach":"Menjalankan eksperimen faktorial untuk konsentrasi asam, temperatur, dan waktu; mengukur Ni terlarut dengan AAS; memeriksa residu dengan XRD.","result":"Menemukan rentang kondisi yang menaikkan perolehan menjadi sekitar 85% (angka contoh) sambil membatasi ikut larutnya besi."}'::jsonb, 0);
insert into public.case_studies (id, title, context, year, icon, tags, problem, approach, result, photos, tr, sort) values ('cs2', 'Tracing Copper Losses in a Flotation Circuit', 'Case study · Process analysis', 2024, 'gauge', array['Mass Balance','Flotation']::text[], 'Plant data showed copper recovery dropping without a clear source between rougher, cleaner and scavenger stages.', 'Reconciled assay and flow data into a stage-by-stage mass balance and compared scenarios in a spreadsheet model.', 'Located the largest loss at the scavenger tailings and proposed a regrind step (example outcome).', '[]'::jsonb, '{"t":"Menelusuri Kehilangan Tembaga di Sirkuit Flotasi","ctx":"Studi kasus · Analisis proses","problem":"Data pabrik menunjukkan perolehan tembaga turun tanpa sumber yang jelas di antara tahap rougher, cleaner, dan scavenger.","approach":"Merekonsiliasi data assay dan aliran menjadi neraca massa per tahap, lalu membandingkan skenario di model spreadsheet.","result":"Menemukan kehilangan terbesar di tailing scavenger dan mengusulkan tahap regrind (hasil contoh)."}'::jsonb, 1);
